-- Add 'Practice' to check_quest_type constraint (needed for Tune tab daily practices)
ALTER TABLE quest_completions DROP CONSTRAINT IF EXISTS check_quest_type;
ALTER TABLE quest_completions ADD CONSTRAINT check_quest_type CHECK (quest_type = ANY (ARRAY['daily','weekly','anytime','challenge','Daily','Weekly','flow','Movement Maker','Vibe Riser','Vibe Riser, Movement Maker','Recognise','Release','Rewire','Reconnect','recognise','release','rewire','reconnect','Tracker','Tracking','groan','Validation','Product','Testing','Money Models','Campaign','Launch','Flow Finder','Offer Creation','Rest','Practice']));
